  const near=r.locator.nearest(p.pos.x,p.pos.z);
  const idx=near.index;
  const v=Math.hypot(p.vel.x,p.vel.z);
  // lookahead
  const aheadM = 6 + v*0.35;
  const ahead = Math.round(aheadM / (t.length/N));
  const s=t.samples[(idx+ahead)%N];
  const desired=Math.atan2(s.x-p.pos.x, s.z-p.pos.z);
  let err=wrap(desired-p.yaw);
  a.input.steerAxis=Math.max(-1,Math.min(1,err*3.0));
  // target speed based on lookahead curvature
  let minR=1e9;
  for(let d=0; d<Math.round(50/(t.length/N)); d++){
    const maybe=1/Math.max(Math.abs(t.samples[(idx+d)%N].k),1e-5);
    if(maybe<minR)minR=maybe;
  }
  // leave margin
  const vmax=Math.min(88, Math.sqrt(45*minR));
  a.input.gas = v < vmax;
  a.input.brake = v > vmax+2;
  // metrics
  log.frames++;
  log.maxDist=Math.max(log.maxDist,near.dist);
  log.minSpeed=Math.min(log.minSpeed,v);
  log.maxSpeed=Math.max(log.maxSpeed,v);
